#!/usr/bin/env bash
# Run the fpga_ids_core testbenches in Questa.
#   ./run_sim.sh [engine|top|hps|all]     (default all)
# Golden vectors are read from ../../rtl/data (generated by
# rtl/scripts/gen_rtl_data.py and checked bit-exact against QKeras).
set -euo pipefail
cd "$(dirname "$0")"

QUESTA="${QUESTA_BIN:-/c/altera_lite/25.1std/questa_fse/win64}"
export PATH="$QUESTA:$PATH"
WHICH="${1:-all}"
STATUS=0

run() {   # run <top> <sources...>
    local top=$1; shift
    rm -rf "work_$top"
    vlib "work_$top" >/dev/null
    vlog -sv -svinputport=var -work "work_$top" "$@" | grep -E "Error|Warning" || true
    local out
    out=$(vsim -c -lib "work_$top" "$top" +DATA=../../rtl/data -do "run -all; quit -f")
    echo "$out" | grep -E "^# (RESULT|PASS|FAIL|SW=|free-run|autostart|sample)" || true
    echo "$out" | grep -q "^# PASS" || STATUS=1
}

CORE="../ids_cnn1d_weights.sv ../ids_cnn1d_engine.sv"
case "$WHICH" in engine|all) echo "== engine";  run tb_ids_cnn1d_engine  $CORE tb_ids_cnn1d_engine.sv ;; esac
case "$WHICH" in top|all)    echo "== board top"; run tb_de1_soc_ids_top $CORE ../sample_rom.sv ../hex_decoder.sv ../de1_soc_ids_top.sv tb_de1_soc_ids_top.sv ;; esac
case "$WHICH" in hps|all)    echo "== HPS Avalon-MM wrapper"; run tb_ids_cnn1d_hps_avmm $CORE ../hps/ids_cnn1d_hps_avmm.sv tb_ids_cnn1d_hps_avmm.sv ;; esac
exit $STATUS
